def _spread(lessons):
    import hashlib
    for L in lessons:
        for i, x in enumerate(L["quiz"]):
            n = len(x["o"])
            want = int(hashlib.sha1(f"{L['id']}#{i}".encode()).hexdigest(), 16) % n
            k = (x["a"] - want) % n
            x["o"] = x["o"][k:] + x["o"][:k]
            x["a"] = want


_spread(LESSONS)
